1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type StepResult = { premium: number };
19	
20	export type ScenarioResult = { results: StepResult[] };
21	
22	const BASE_PRICE_BY_TYPE: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	};
28	
29	const FIRST_INSURANCE_SURCHARGE = 1.1;
30	const CONTRACT_FEE = 5;
31	
32	// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
33	// no test yet lands on a half-way value, so the rounding *direction* stays
34	// unspecified until the "rounds in MHPCO's favor" test pins it.
35	const quotePremium = (item: Item): number =>
36	  Math.round(BASE_PRICE_BY_TYPE[item.type] * FIRST_INSURANCE_SURCHARGE) + CONTRACT_FEE;
37	
38	export const runScenario = (scenario: Scenario): ScenarioResult => {
39	  const item = scenario.steps[0].items![0];
40	  return { results: [{ premium: quotePremium(item) }] };
41	};
